text:
{
  "title_novice": "Пороги для показаний приборов",
  "summary": [
    {"text": "Граничное значение геофизического параметра не берут с прибора напрямую. Его выводят через связь с коллекторским свойством.", "claims": ["c1"]},
    {"text": "Для продуктивных пород эту связь строят по интервалам испытаний, где проницаемость рассчитана по гидродинамическим данным.", "claims": ["c6", "c7"]},
    {"text": "Затем по уравнению регрессии находят граничное значение параметра для заданного критического K*пр.", "claims": ["c9"]}
  ],
  "claims": [
    {"key": "c1", "text": "Граничные значения геофизических параметров устанавливают на основе корреляционных связей с коллекторским свойством или глинистостью.", "kind": "inference", "unit_id": "u-010-92d3a4", "page": 10, "quote": "устанавливаются на основе корреляционных связей между этим параметром и соответствующим ему параметром", "numbers": [], "question": null},
    {"key": "c2", "text": "Автор выделяет три наиболее типичных вида таких связей.", "kind": "observation", "unit_id": "u-010-92d3a4", "page": 10, "quote": "Наиболее типичные связи такого рода следующие", "numbers": [], "question": null},
    {"key": "c3", "text": "Первый вид связи: геофизический параметр и коэффициент проницаемости.", "kind": "observation", "unit_id": "u-010-92d3a4", "page": 10, "quote": "между геофизическими параметрами и коэффициентом проницаемости", "numbers": [], "question": null},
    {"key": "c4", "text": "Второй вид связи: геофизические параметры пористости и коэффициент пористости.", "kind": "observation", "unit_id": "u-010-92d3a4", "page": 10, "quote": "между геофизическими параметрами, характеризующими пористость, и коэффициентом пористости", "numbers": [], "question": null},
    {"key": "c5", "text": "Третий вид связи: геофизические параметры глинистости и параметры глинистости.", "kind": "observation", "unit_id": "u-010-92d3a4", "page": 10, "quote": "между геофизическими параметрами, характеризующими глинистость, и параметрами глинистости", "numbers": [], "question": null},
    {"key": "c6", "text": "Для продуктивных отложений связь геофизических параметров с проницаемостью строят по интервалам испытаний или пробной эксплуатации.", "kind": "observation", "unit_id": "u-010-0c4525", "page": 10, "quote": "Корреляционную связь между геофизическими параметрами $\\mathrm{P}_{\\mathrm{n}}, \\alpha_{\\mathrm{CII}}, \\Delta \\mathrm{J}_{\\mathrm{T}}$ и коэффициентом проницаемости для продуктивных отложений устанавливают, сопоставляя по интервалам испытаний (или пробной эксплуатации)", "numbers": [], "question": "q1"},
    {"key": "c7", "text": "Проницаемость для интервала берут из гидродинамических исследований по кривой восстановления давления.", "kind": "observation", "unit_id": "u-010-0c4525", "page": 10, "quote": "рассчитана по данным гидродинамических исследований (по кривой восстановления давления)", "numbers": [], "question": null},
    {"key": "c8", "text": "Интервалы для связи должны быть достаточно однородными по геофизической характеристике.", "kind": "assumption", "unit_id": "u-010-0c4525", "page": 10, "quote": "Интервалы должны быть достаточно однородными по геофизической характеристике", "numbers": [], "question": null},
    {"key": "c9", "text": "По уравнению регрессии для заданного критического значения проницаемости находят граничное значение геофизического параметра.", "kind": "inference", "unit_id": "u-010-0c4525", "page": 10, "quote": "в соответствии с уравнением регрессии для заданного значения", "numbers": [], "question": null},
    {"key": "c10", "text": "Для каждого интервала сопоставляют проницаемость и усреднённое по интервалу значение геофизического параметра.", "kind": "observation", "unit_id": "u-010-0c4525", "page": 10, "quote": "и усредненное для этого интервала значение геофизического параметра", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "Геофизический параметр связан с коллекторским свойством через корреляцию. Он не равен этому свойству.", "claims": ["c1"], "hypothesis": false},
    {"text": "Граница на шкале параметра соответствует заданному значению коллекторского свойства через уравнение регрессии.", "claims": ["c9"], "hypothesis": false},
    {"text": "Автор называет три типичные связи геофизических параметров с коллекторскими свойствами и глинистостью.", "claims": ["c2"], "hypothesis": false},
    {"text": "Связь с проницаемостью для продуктивных отложений строят по интервалам испытаний или пробной эксплуатации.", "claims": ["c6"], "hypothesis": false},
    {"text": "Проницаемость интервала известна из гидродинамики, а геофизический параметр усредняют по тому же интервалу.", "claims": ["c7", "c10"], "hypothesis": false}
  ],
  "practice": [
    {"text": "Специалист выбирает интервалы испытаний, где проницаемость рассчитана по гидродинамическим данным.", "claims": ["c7"], "hypothesis": false},
    {"text": "Признак пригодности интервала — его однородность по геофизической характеристике.", "claims": ["c8"], "hypothesis": false},
    {"text": "Для каждого интервала сопоставляют проницаемость и среднее значение параметра. По ним строят связь и находят граничное значение.", "claims": ["c6", "c10", "c9"], "hypothesis": false}
  ],
  "nuances": [
    {"text": "Связь с проницаемостью строят только по интервалам, где проницаемость рассчитана по гидродинамическим данным.", "claims": ["c7"], "hypothesis": false},
    {"text": "Интервалы должны быть достаточно однородными по геофизической характеристике. Иначе среднее по интервалу плохо описывает его свойства.", "claims": ["c8"], "hypothesis": false},
    {"text": "Вид связи зависит от параметра: проницаемость, пористость или глинистость. Для каждого нужна своя связь.", "claims": ["c3", "c4", "c5"], "hypothesis": false},
    {"text": "Граничное значение параметра зависит от выбранного критического значения, для которого берут регрессию.", "claims": ["c9"], "hypothesis": false}
  ],
  "deeper": [
    {"title": "Что обычно записывают как кривую восстановления давления", "text": "Такую кривую обычно получают после остановки скважины, когда давление в пласте восстанавливается. В главе детали не раскрыты.", "claims": [], "hypothesis": true},
    {"title": "Почему смешанный интервал мешает", "text": "Если интервал содержит разные породы, одно среднее значение параметра плохо описывает его проницаемость. Это рассуждение вне главы.", "claims": [], "hypothesis": true}
  ],
  "procedure": [
    {"text": "Выбрать интервалы испытаний или пробной эксплуатации, где проницаемость рассчитана по гидродинамическим исследованиям.", "claims": ["c6", "c7"]},
    {"text": "Проверить, что интервал достаточно однороден по геофизической характеристике.", "claims": ["c8"]},
    {"text": "Для каждого интервала взять проницаемость и усреднённое значение геофизического параметра.", "claims": ["c10"]},
    {"text": "По уравнению регрессии для заданного критического значения проницаемости найти граничное значение параметра.", "claims": ["c9"]}
  ],
  "numbers_conditions": [
    {"text": "Связь строят для продуктивных отложений по интервалам, где проницаемость получена из гидродинамики.", "claims": ["c6", "c7"]},
    {"text": "Интервалы должны быть достаточно однородными по геофизической характеристике.", "claims": ["c8"]},
    {"text": "Граничное значение параметра определяют по уравнению регрессии при заданном критическом значении проницаемости.", "claims": ["c9"]}
  ],
  "terms_defined": [
    {"term": "гидродинамические исследования", "term_en": "hydrodynamic studies", "abbr": "", "definition": "В главе — источник расчёта проницаемости для интервала испытания. Методика самих исследований здесь не раскрыта.", "claims": ["c7"]},
    {"term": "кривая восстановления давления", "term_en": "pressure buildup curve", "abbr": "", "definition": "Кривая, по которой в гидродинамических исследованиях рассчитывают проницаемость интервала. Как именно, в главе не раскрыто.", "claims": ["c7"]},
    {"term": "интервал испытания", "term_en": "test interval", "abbr": "", "definition": "Участок разреза, который испытали или пробно эксплуатировали. Для него известны проницаемость и средний геофизический параметр.", "claims": ["c6", "c10"]}
  ],
  "terms_used": ["граничное (критическое) значение", "K*пр", "K*п", "Kпр", "Kп", "корреляционная связь", "уравнение регрессии", "α*СП", "ΔJγ", "ηгл", "Pн", "Cгл", "Kгл", "ГИС"],
