    "wrong": "Граница на каротажной кривой — это прямой признак породы. Кривая сама показывает проницаемость пласта.",
    "right": "Граничное значение параметра выводят из корреляции с проницаемостью, полученной по испытаниям. Сам параметр — косвенный отклик.",
    "claims": ["c1", "c6", "c9"]
  },
  "data_meaning": {
    "inputs": [
      {"text": "Интервалы испытаний или пробной эксплуатации с проницаемостью из гидродинамических данных.", "claims": ["c7"], "hypothesis": false},
      {"text": "Усреднённые по интервалу значения геофизического параметра.", "claims": ["c10"], "hypothesis": false},
      {"text": "Оценка однородности интервала по геофизической характеристике.", "claims": ["c8"], "hypothesis": false}
    ],
    "outputs": [
      {"text": "Корреляционная связь и уравнение регрессии между параметром и проницаемостью для продуктивных отложений.", "claims": ["c6"], "hypothesis": false},
      {"text": "Граничное значение параметра для заданного критического значения проницаемости.", "claims": ["c9"], "hypothesis": false}
    ],
    "breaks": [
      {"text": "Неоднородный интервал даёт среднее значение, которое плохо отвечает одному значению проницаемости.", "claims": ["c8"], "hypothesis": false},
      {"text": "Связь строится только там, где есть интервалы с гидродинамической оценкой проницаемости.", "claims": ["c7"], "hypothesis": true}
    ]
  },
  "it_analogy": {
    "pack_id": "IT01",
    "analogy": "Каротажный параметр похож на метрику мониторинга: это отклик датчика. Его порог калибруют по независимому эталону, здесь — по испытаниям.",
    "breaks_where": "У породы нет логов системы для калибровки. Эталон — испытания, и они есть не для всех интервалов."
  },
  "now_nuance": null,
